import{_ as a}from"./chunks/console-application-banking.DYnJShAE.js";import{_ as t,o as s,c as i,a3 as o}from"./chunks/framework.DhF4LrUq.js";const k=JSON.parse('{"title":"Developer quickstart","description":"Quickstart for Developers — artifact upload with provenance, versions, CI integrations, and gate feedback, from the CLI and the Console.","frontmatter":{"description":"Quickstart for Developers — artifact upload with provenance, versions, CI integrations, and gate feedback, from the CLI and the Console."},"headers":[],"relativePath":"roles/developer.md","filePath":"roles/developer.md"}'),r={name:"roles/developer.md"};function n(l,e,h,p,d,c){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="developer-quickstart" tabindex="-1">Developer quickstart <a class="header-anchor" href="#developer-quickstart" aria-label="Permalink to &quot;Developer quickstart&quot;">​</a></h1><h2 id="who-you-are" tabindex="-1">Who you are <a class="header-anchor" href="#who-you-are" aria-label="Permalink to &quot;Who you are&quot;">​</a></h2><p>You ship the bytes. Your system role is <strong><code>DEVELOPER</code></strong>, and your primary surfaces are the CLI and your CI pipeline, with the Console for watching what happens to what you shipped. In the whole role catalog the artifact-upload permission belongs to your role and the platform administrator alone — app owners and release managers can read artifacts, but you are the one who puts them there. You upload builds with their provenance, watch validation settle, follow your builds through releases, and wire the CI that does it all automatically. If you also own applications or run releases, pick one track per session and use the <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a> and <a href="/shipperdog/snapshot/roles/release-manager">Release Manager</a> guides for those hats.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><ul><li><strong>Upload artifacts</strong> — IPA, APK, and AAB files, directly (multipart) or through resumable sessions for large builds, with provenance captured automatically: who, from where, built when.</li><li><strong>Read the pipeline</strong> — every artifact&#39;s validation state, extracted metadata (build number, minimum OS, version name), and history.</li><li><strong>Follow releases</strong> — read the releases your builds ride, the gates that reference your evidence, and the approval chains around them.</li><li><strong>See the rules</strong> — read-only visibility into environments, approval workflows, gate definitions, rings, release policies, ABAC policies, and notification routing: everything that decides what happens to your build after upload, nothing you can change. Version tags, lifecycles, and release driving belong to the <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a> and <a href="/shipperdog/snapshot/roles/release-manager">Release Manager</a> tracks.</li></ul><h2 id="first-15-minutes" tabindex="-1">First 15 minutes <a class="header-anchor" href="#first-15-minutes" aria-label="Permalink to &quot;First 15 minutes&quot;">​</a></h2><p>The screenshots come from the locally running development stack with its seeded demo world — what you see here is what you will see there.</p><ol><li><p><strong>Install and log in with the CLI.</strong> <code>shipperdog login</code> stores your credentials under <code>~/.shipperdog</code> (or point <code>SHIPPERDOG_API</code> and <code>SHIPPERDOG_TOKEN</code> at another instance):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> banking</span></span></code></pre></div></li><li><p><strong>Upload a build.</strong> Point the uploader at the version your App Owner created — by name, with provenance flags your CI can supply:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shipperdog</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artifact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app-release.apk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> banking</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.2.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --platform</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android</span></span></code></pre></div><p>The upload streams (large builds ride resumable sessions direct to storage), lands with a SHA-256 computed in-stream, and the artifact is born <code>VALIDATING</code>.</p></li><li><p><strong>Watch validation settle.</strong> Metadata extraction reads the build number, version name, and minimum OS out of the package; provenance is recorded; the state moves to <code>READY</code> — or <code>FAILED</code> with the reason. <code>shipperdog artifact view</code> shows the extraction results.</p></li><li><p><strong>Check the slot in the Console.</strong> Open your application and see the version&#39;s platform slots carry your artifact with its build facts — the same page your App Owner and Release Manager watch:</p><p><img src="`+a+'" alt="The Banking application detail"></p></li><li><p><strong>Wire CI so this stops being manual.</strong> The same verbs run from GitHub Actions, Jenkins, or GitLab — upload on tag, gate results on test completion. The integrations land in the automation how-tos, starting with the <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a> and <a href="/shipperdog/snapshot/how-to/automation/github-actions">GitHub Actions</a>; the topology is sketched in <a href="/shipperdog/snapshot/concepts/architecture">architecture</a>.</p></li></ol><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>Hand-off task list:</p><ul><li>[ ] Read <a href="/shipperdog/snapshot/concepts/artifact-pipeline">the artifact pipeline</a> — what happens between your upload and READY</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/architecture">architecture</a> for how CI fits in</li><li>[ ] Read <a href="/shipperdog/snapshot/concepts/release-lifecycle">the release lifecycle</a> to know where your build goes next</li><li>[ ] How-tos as they land: <a href="/shipperdog/snapshot/how-to/automation/cli-reference">CLI reference</a>, <a href="/shipperdog/snapshot/how-to/automation/github-actions">GitHub Actions</a></li><li>[ ] Self-updating app? <a href="/shipperdog/snapshot/how-to/ota-sdk">Integrate the OTA SDK</a> (Kotlin or Swift) so your build checks, verifies, and applies OTA bundles</li><li>[ ] Ask your App Owner for the version slot before your first upload (versions are created on the <a href="/shipperdog/snapshot/roles/app-owner">App Owner</a> track)</li></ul>',11)])])}const f=t(r,[["render",n]]);export{k as __pageData,f as default};
